tool_schemas.implementation:
def sequentialthinking_tools(thought, next_thought_needed, thought_number, total_thoughts, is_revision=None, revises_thought=None, branch_from_thought=None, branch_id=None, needs_more_thoughts=None, current_step=None, previous_steps=None, remaining_steps=None, **_extra):
    import json, os, datetime, time, uuid, math
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0517000" if __import__("os").path.isdir("./environment_mix/0517000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    now = now_dt.isoformat().replace("+00:00", "Z")

    def _parse_ts(ts):
        if not isinstance(ts, str) or not ts:
            return None
        try:
            return datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
        except Exception:
            return None

    def _new_id(prefix):
        return f"{prefix}{uuid.uuid4().hex}"

    def _log(endpoint, status, api_key_id=None, workspace_id=None, session_id=None, message=None, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": endpoint,
            "api_key_id": api_key_id,
            "workspace_id": workspace_id,
            "session_id": session_id,
            "status": status,
            "message": message,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "created_at": now,
        }
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_limits(api_key_id, workspace_id):
        # Default dynamics (since no explicit quota tables in schema provided here)
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        one_min_ago = now_dt - datetime.timedelta(minutes=1)
        day_ago = now_dt - datetime.timedelta(days=1)
        rpm = 0
        wday = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            ts = _parse_ts(r.get("created_at"))
            if ts is None:
                continue
            if api_key_id and r.get("api_key_id") == api_key_id and ts >= one_min_ago:
                rpm += 1
            if workspace_id and r.get("workspace_id") == workspace_id and ts >= day_ago:
                wday += 1
        # Conservative but functional defaults
        if rpm >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded (120 requests/min per key).", limit="120/min", scope="api_key")
        if wday >= 20000:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded (20000 requests/day per workspace).", limit="20000/day", scope="workspace")
        return None

    def _validate_step_obj(step_obj):
        if not isinstance(step_obj, dict):
            return _err("VALIDATION_ERROR", "Step must be an object.")
        for k in ("step_description", "recommended_tools", "expected_outcome"):
            if k not in step_obj:
                return _err("VALIDATION_ERROR", f"Step missing required field '{k}'.", field=k)
        if not isinstance(step_obj.get("step_description"), str) or not step_obj["step_description"].strip():
            return _err("VALIDATION_ERROR", "step_description must be a non-empty string.", field="step_description")
        if not isinstance(step_obj.get("expected_outcome"), str) or not step_obj["expected_outcome"].strip():
            return _err("VALIDATION_ERROR", "expected_outcome must be a non-empty string.", field="expected_outcome")
        rt = step_obj.get("recommended_tools")
        if not isinstance(rt, list) or len(rt) < 1:
            return _err("VALIDATION_ERROR", "recommended_tools must be a non-empty array.", field="recommended_tools")
        for i, rec in enumerate(rt):
            if not isinstance(rec, dict):
                return _err("VALIDATION_ERROR", "recommended_tools items must be objects.", index=i)
            for k in ("tool_name", "confidence", "rationale", "priority"):
                if k not in rec:
                    return _err("VALIDATION_ERROR", f"recommended_tools[{i}] missing required field '{k}'.", field=k, index=i)
            if not isinstance(rec.get("tool_name"), str) or not rec["tool_name"].strip():
                return _err("VALIDATION_ERROR", f"recommended_tools[{i}].tool_name must be a non-empty string.", field="tool_name", index=i)
            conf = rec.get("confidence")
            if not isinstance(conf, (int, float)) or isinstance(conf, bool) or math.isnan(float(conf)) or float(conf) < 0 or float(conf) > 1:
                return _err("VALIDATION_ERROR", f"recommended_tools[{i}].confidence must be a number between 0 and 1.", field="confidence", index=i)
            pr = rec.get("priority")
            if not isinstance(pr, (int, float)) or isinstance(pr, bool) or math.isnan(float(pr)) or not math.isfinite(float(pr)):
                return _err("VALIDATION_ERROR", f"recommended_tools[{i}].priority must be a finite number.", field="priority", index=i)
            if not isinstance(rec.get("rationale"), str):
                return _err("VALIDATION_ERROR", f"recommended_tools[{i}].rationale must be a string.", field="rationale", index=i)
            if "alternatives" in rec and rec["alternatives"] is not None:
                if not isinstance(rec["alternatives"], list) or any((not isinstance(x, str)) for x in rec["alternatives"]):
                    return _err("VALIDATION_ERROR", f"recommended_tools[{i}].alternatives must be an array of strings.", field="alternatives", index=i)
            if "suggested_inputs" in rec and rec["suggested_inputs"] is not None and not isinstance(rec["suggested_inputs"], dict):
                return _err("VALIDATION_ERROR", f"recommended_tools[{i}].suggested_inputs must be an object.", field="suggested_inputs", index=i)
        if "next_step_conditions" in step_obj and step_obj["next_step_conditions"] is not None:
            if not isinstance(step_obj["next_step_conditions"], list) or any((not isinstance(x, str)) for x in step_obj["next_step_conditions"]):
                return _err("VALIDATION_ERROR", "next_step_conditions must be an array of strings.", field="next_step_conditions")
        return None

    # ---- Validate required inputs ----
    if not isinstance(thought, str) or not thought.strip():
        _log("sequentialthinking_tools", "error", message="Invalid thought", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "thought must be a non-empty string.", field="thought")
    if not isinstance(next_thought_needed, bool):
        _log("sequentialthinking_tools", "error", message="Invalid next_thought_needed", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "next_thought_needed must be boolean.", field="next_thought_needed")
    if not isinstance(thought_number, int) or isinstance(thought_number, bool) or thought_number < 1:
        _log("sequentialthinking_tools", "error", message="Invalid thought_number", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "thought_number must be an integer >= 1.", field="thought_number")
    if not isinstance(total_thoughts, int) or isinstance(total_thoughts, bool) or total_thoughts < 1:
        _log("sequentialthinking_tools", "error", message="Invalid total_thoughts", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "total_thoughts must be an integer >= 1.", field="total_thoughts")

    if is_revision is None:
        is_revision = False
    if not isinstance(is_revision, bool):
        _log("sequentialthinking_tools", "error", message="Invalid is_revision", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "is_revision must be boolean.", field="is_revision")
    if needs_more_thoughts is not None and not isinstance(needs_more_thoughts, bool):
        _log("sequentialthinking_tools", "error", message="Invalid needs_more_thoughts", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "needs_more_thoughts must be boolean when provided.", field="needs_more_thoughts")

    # Parameter names map: tool uses revises_thought/branch_from_thought; store uses revises_thought_number/branch_from_thought_number
    if is_revision:
        if not isinstance(revises_thought, int) or isinstance(revises_thought, bool) or revises_thought < 1:
            _log("sequentialthinking_tools", "error", message="Missing/invalid revises_thought", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "revises_thought must be an integer >= 1 when is_revision=true.", field="revises_thought")
    else:
        if revises_thought is not None:
            _log("sequentialthinking_tools", "error", message="revises_thought with is_revision=false", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "revises_thought must be null when is_revision=false.", field="revises_thought")

    if branch_from_thought is not None:
        if not isinstance(branch_from_thought, int) or isinstance(branch_from_thought, bool) or branch_from_thought < 1:
            _log("sequentialthinking_tools", "error", message="Invalid branch_from_thought", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "branch_from_thought must be an integer >= 1 when provided.", field="branch_from_thought")
        if not isinstance(branch_id, str) or not branch_id.strip():
            _log("sequentialthinking_tools", "error", message="branch_id required when branching", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "branch_id must be provided when branch_from_thought is set.", field="branch_id")

    if branch_id is not None and (not isinstance(branch_id, str) or not branch_id.strip()):
        _log("sequentialthinking_tools", "error", message="Invalid branch_id", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "branch_id must be a non-empty string when provided.", field="branch_id")

    if current_step is not None:
        e = _validate_step_obj(current_step)
        if e:
            _log("sequentialthinking_tools", "error", message=e["error"]["message"], error_code=e["error"]["code"])
            return e
    if previous_steps is not None:
        if not isinstance(previous_steps, list):
            _log("sequentialthinking_tools", "error", message="Invalid previous_steps", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "previous_steps must be an array when provided.", field="previous_steps")
        for j, st in enumerate(previous_steps):
            e = _validate_step_obj(st)
            if e:
                _log("sequentialthinking_tools", "error", message=e["error"]["message"], error_code=e["error"]["code"])
                e["error"]["index"] = j
                return e
    if remaining_steps is not None:
        if not isinstance(remaining_steps, list) or any((not isinstance(x, str)) for x in remaining_steps):
            _log("sequentialthinking_tools", "error", message="Invalid remaining_steps", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "remaining_steps must be an array of strings when provided.", field="remaining_steps")

    # ---- Authenticate ambiently: choose any active api_key whose workspace is active ----
    api_keys = _load("api_keys.json")
    if isinstance(api_keys, dict) and "rows" in api_keys:
        api_keys = api_keys.get("rows")
    if not isinstance(api_keys, list):
        api_keys = []
    workspaces = _load("workspaces.json")
    if isinstance(workspaces, dict) and "rows" in workspaces:
        workspaces = workspaces.get("rows")
    if not isinstance(workspaces, list):
        workspaces = []

    ws_by_id = {w.get("id"): w for w in workspaces if isinstance(w, dict) and isinstance(w.get("id"), str)}
    active_key = None
    active_ws = None
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("status") != "active":
            continue
        ws = ws_by_id.get(k.get("workspace_id"))
        if not ws or ws.get("status") != "active":
            continue
        allowed = k.get("allowed_tools")
        if isinstance(allowed, list) and len(allowed) >= 1:
            active_key = k
            active_ws = ws
            break

    if not active_key or not active_ws:
        _log("sequentialthinking_tools", "error", message="No active api key/workspace available", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active API key in an active workspace is available to serve this request.")

    lim = _enforce_limits(active_key.get("id"), active_ws.get("id"))
    if lim:
        _log("sequentialthinking_tools", "error", api_key_id=active_key.get("id"), workspace_id=active_ws.get("id"), message=lim["error"]["message"], error_code=lim["error"]["code"])
        return lim

    # ---- Determine/resolve session: most recent active session for this workspace+key; else create implicitly ----
    sessions = _load("thinking_sessions.json")
    if isinstance(sessions, dict) and "rows" in sessions:
        sessions = sessions.get("rows")
    if not isinstance(sessions, list):
        sessions = []

    def _session_sort_key(s):
        ts = _parse_ts(s.get("updated_at")) or _parse_ts(s.get("created_at")) or now_dt
        return ts

    candidate_sessions = [
        s for s in sessions
        if isinstance(s, dict)
        and s.get("workspace_id") == active_ws.get("id")
        and (s.get("api_key_id") in (None, active_key.get("id")))
        and s.get("status") == "active"
    ]
    candidate_sessions.sort(key=_session_sort_key, reverse=True)
    session = candidate_sessions[0] if candidate_sessions else None

    # Create implicit session if none exists
    if session is None:
        # enforce workspace active session quota
        active_count = 0
        for s in sessions:
            if isinstance(s, dict) and s.get("workspace_id") == active_ws.get("id") and s.get("status") == "active":
                active_count += 1
        max_active = active_ws.get("max_active_sessions")
        if not isinstance(max_active, int) or isinstance(max_active, bool) or max_active < 1:
            _log("sequentialthinking_tools", "error", api_key_id=active_key.get("id"), workspace_id=active_ws.get("id"), message="Workspace max_active_sessions invalid", error_code="CONFLICT")
            return _err("CONFLICT", "Workspace configuration invalid: max_active_sessions must be >= 1.", workspace_id=active_ws.get("id"))
        if active_count >= max_active:
            _log("sequentialthinking_tools", "error", api_key_id=active_key.get("id"), workspace_id=active_ws.get("id"), message="Active session quota exceeded", error_code="QUOTA_EXCEEDED")
            return _err("QUOTA_EXCEEDED", "Workspace active-session quota exceeded.", workspace_id=active_ws.get("id"), max_active_sessions=max_active)

        tool_ctx = active_key.get("allowed_tools")
        if not isinstance(tool_ctx, list) or len(tool_ctx) < 1:
            _log("sequentialthinking_tools", "error", api_key_id=active_key.get("id"), workspace_id=active_ws.get("id"), message="API key has no allowed_tools", error_code="UNAUTHORIZED")
            return _err("UNAUTHORIZED", "Authenticated API key has no allowed tools.")
        sess_id = "st_sess_" + uuid.uuid4().hex[:26].upper()
        session = {
            "id": sess_id,
            "workspace_id": active_ws.get("id"),
            "api_key_id": active_key.get("id"),
            "status": "active",
            "title": None,
            "tool_context": list(tool_ctx),
            "current_thought_number": 0,
            "estimated_total_thoughts": int(total_thoughts),
            "next_thought_needed": bool(next_thought_needed),
            "needs_more_thoughts": needs_more_thoughts if needs_more_thoughts is not None else None,
            "remaining_steps": remaining_steps if remaining_steps is not None else None,
            "created_at": now,
            "updated_at": now,
            "completed_at": None,
        }
        sessions.append(session)
        _save("thinking_sessions.json", sessions)

    # Validate session tool_context
    tool_context_sess = session.get("tool_context")
    if not isinstance(tool_context_sess, list) or len(tool_context_sess) < 1:
        _log("sequentialthinking_tools", "error", api_key_id=active_key.get("id"), workspace_id=active_ws.get("id"), session_id=session.get("id"), message="Session tool_context invalid", error_code="CONFLICT")
        return _err("CONFLICT", "Session tool_context invalid; must be a non-empty array.", session_id=session.get("id"))

    # Enforce tool recommendations tool_name in session tool_context
    sess_tool_set = set([t for t in tool_context_sess if isinstance(t, str)])

    def _validate_recs_in_ctx(step_obj):
        rt = step_obj.get("recommended_tools", [])
        for i, rec in enumerate(rt):
            tn = rec.get("tool_name")
            if tn not in sess_tool_set:
                return _err("VALIDATION_ERROR", "Tool recommendation includes tool_name outside session tool_context.", tool_name=tn, session_id=session.get("id"))
        return None

    if current_step is not None:
        e = _validate_recs_in_ctx(current_step)
        if e:
            _log("sequentialthinking_tools", "error", api_key_id=active_key.get("id"), workspace_id=active_ws.get("id"), session_id=session.get("id"), message=e["error"]["message"], error_code=e["error"]["code"])
            return e
    if previous_steps is not None:
        for st in previous_steps:
            e = _validate_recs_in_ctx(st)
            if e:
                _log("sequentialthinking_tools", "error", api_key_id=active_key.get("id"), workspace_id=active_ws.get("id"), session_id=session.get("id"), message=e["error"]["message"], error_code=e["error"]["code"])
                return e

    # ---- Load thoughts for the session; validate revision/branch rules & quotas ----
    thoughts = _load("thoughts.json")
    if isinstance(thoughts, dict) and "rows" in thoughts:
        thoughts = thoughts.get("rows")
    if not isinstance(thoughts, list):
        thoughts = []

    sess_id = session.get("id")
    sess_thoughts = [t for t in thoughts if isinstance(t, dict) and t.get("session_id") == sess_id]
    non_deleted_count = sum(1 for t in sess_thoughts if t.get("status") != "deleted")
    max_thoughts = active_ws.get("max_thoughts_per_session")
    if not isinstance(max_thoughts, int) or isinstance(max_thoughts, bool) or max_thoughts < 1:
        _log("sequentialthinking_tools", "error", api_key_id=active_key.get("id"), workspace_id=active_ws.get("id"), session_id=sess_id, message="Workspace max_thoughts_per_session invalid", error_code="CONFLICT")
        return _err("CONFLICT", "Workspace configuration invalid: max_thoughts_per_session must be >= 1.", workspace_id=active_ws.get("id"))
    if non_deleted_count >= max_thoughts:
        _log("sequentialthinking_tools", "error", api_key_id=active_key.get("id"), workspace_id=active_ws.get("id"), session_id=sess_id, message="Thought quota exceeded", error_code="QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Session thought quota exceeded.", session_id=sess_id, max_thoughts_per_session=max_thoughts)

    # Validate branch_from_thought exists if provided
    def _find_existing_thought_num(n, branch=None):
        for t in sess_thoughts:
            if t.get("status") == "deleted":
                continue
            if t.get("thought_number") == n and (branch is None or t.get("branch_id") == branch):
                return t
        return None

    if branch_from_thought is not None:
        base = _find_existing_thought_num(branch_from_thought, branch=None)
        if not base:
            _log("sequentialthinking_tools", "error", api_key_id=active_key.get("id"), workspace_id=active_ws.get("id"), session_id=sess_id, message="branch_from_thought not found", error_code="NOT_FOUND")
            return _err("NOT_FOUND", "branch_from_thought must refer to an existing non-deleted thought_number in the session.", session_id=sess_id, branch_from_thought=branch_from_thought)

    # Validate revises_thought exists within session (non-deleted). Prefer same branch_id if provided.
    if is_revision:
        target = _find_existing_thought_num(revises_thought, branch=branch_id) if branch_id is not None else _find_existing_thought_num(revises_thought, branch=None)
        if not target:
            _log("sequentialthinking_tools", "error", api_key_id=active_key.get("id"), workspace_id=active_ws.get("id"), session_id=sess_id, message="revises_thought not found", error_code="NOT_FOUND")
            return _err("NOT_FOUND", "revises_thought must refer to an existing non-deleted thought_number in the session.", session_id=sess_id, revises_thought=revises_thought)

    # Non-decreasing rule within branch unless revision or branch changes
    sess_current = session.get("current_thought_number")
    if not isinstance(sess_current, int) or isinstance(sess_current, bool) or sess_current < 0:
        sess_current = 0

    if thought_number < sess_current:
        # allowed only if revision OR branch_id changes compared to last committed thought branch
        allowed = False
        if is_revision:
            allowed = True
        else:
            # determine latest non-deleted committed thought branch_id
            latest = None
            for t in sess_thoughts:
                if t.get("status") == "deleted":
                    continue
                if latest is None or (isinstance(t.get("thought_number"), int) and t.get("thought_number") > latest.get("thought_number", -1)):
                    latest = t
            if latest is not None and latest.get("branch_id") != branch_id:
                allowed = True
        if not allowed:
            _log("sequentialthinking_tools", "error", api_key_id=active_key.get("id"), workspace_id=active_ws.get("id"), session_id=sess_id, message="thought_number decreased without revision/branch change", error_code="INVALID_TRANSITION")
            return _err("INVALID_TRANSITION", "thought_number lower than current_thought_number is only allowed for revisions or when changing branch_id.", session_id=sess_id, current_thought_number=sess_current, thought_number=thought_number)

    # Uniqueness: unique(session_id, thought_number, branch_id) where status != deleted
    for t in sess_thoughts:
        if t.get("status") == "deleted":
            continue
        if t.get("thought_number") == thought_number and t.get("branch_id") == branch_id:
            # idempotency: if same payload, return existing
            if t.get("thought") == thought and t.get("next_thought_needed") == next_thought_needed and t.get("total_thoughts") == total_thoughts and t.get("is_revision") == is_revision:
                # Still update session guidance fields as "accepted tool call" would have (idempotent reapply)
                session["estimated_total_thoughts"] = int(total_thoughts)
                session["next_thought_needed"] = bool(next_thought_needed)
                session["needs_more_thoughts"] = needs_more_thoughts if needs_more_thoughts is not None else session.get("needs_more_thoughts")
                session["remaining_steps"] = remaining_steps if remaining_steps is not None else session.get("remaining_steps")
                session["current_thought_number"] = max(sess_current, int(thought_number))
                session["updated_at"] = now
                if (session.get("status") == "active") and (next_thought_needed is False) and (needs_more_thoughts is False or needs_more_thoughts is None):
                    session["status"] = "completed"
                    session["completed_at"] = now
                for si, srow in enumerate(sessions):
                    if isinstance(srow, dict) and srow.get("id") == sess_id:
                        sessions[si] = session
                        break
                _save("thinking_sessions.json", sessions)
                # log and return
                active_key["last_used_at"] = now
                active_key["updated_at"] = now
                for ki, krow in enumerate(api_keys):
                    if isinstance(krow, dict) and krow.get("id") == active_key.get("id"):
                        api_keys[ki] = active_key
                        break
                _save("api_keys.json", api_keys)
                _log("sequentialthinking_tools", "ok", api_key_id=active_key.get("id"), workspace_id=active_ws.get("id"), session_id=sess_id, message="Idempotent replay")
                return {
                    "session": session,
                    "thought": t,
                }
            _log("sequentialthinking_tools", "error", api_key_id=active_key.get("id"), workspace_id=active_ws.get("id"), session_id=sess_id, message="Duplicate thought_number for branch", error_code="CONFLICT")
            return _err("CONFLICT", "A non-deleted thought already exists with this thought_number and branch_id.", session_id=sess_id, thought_number=thought_number, branch_id=branch_id)

    # ---- Persist new thought ----
    thought_id = "st_tht_" + uuid.uuid4().hex[:26].upper()
    new_thought = {
        "id": thought_id,
        "session_id": sess_id,
        "status": "committed",
        "thought_number": int(thought_number),
        "total_thoughts": int(total_thoughts),
        "thought": thought,
        "next_thought_needed": bool(next_thought_needed),
        "needs_more_thoughts": needs_more_thoughts if needs_more_thoughts is not None else None,
        "is_revision": bool(is_revision),
        "revises_thought_number": int(revises_thought) if is_revision else None,
        "branch_from_thought_number": int(branch_from_thought) if branch_from_thought is not None else None,
        "branch_id": branch_id if branch_id is not None else None,
        "current_step": current_step if current_step is not None else None,
        "previous_steps": previous_steps if previous_steps is not None else None,
        "remaining_steps": remaining_steps if remaining_steps is not None else None,
        "created_at": now,
        "updated_at": now,
    }

    # If revision, supersede the revised thought (if still committed)
    if is_revision:
        for t in thoughts:
            if not isinstance(t, dict):
                continue
            if t.get("session_id") != sess_id:
                continue
            if t.get("status") == "deleted":
                continue
            if t.get("thought_number") == int(revises_thought) and (branch_id is None or t.get("branch_id") == branch_id):
                if t.get("status") == "committed":
                    t["status"] = "superseded"
                    t["updated_at"] = now
                break

    thoughts.append(new_thought)
    _save("thoughts.json", thoughts)

    # ---- Normalize steps into session_steps ----
    steps = _load("session_steps.json")
    if isinstance(steps, dict) and "rows" in steps:
        steps = steps.get("rows")
    if not isinstance(steps, list):
        steps = []

    # Enforce unique(session_id, thought_id, kind); idempotent if already exists
    def _upsert_step(kind, step_obj):
        for st in steps:
            if not isinstance(st, dict):
                continue
            if st.get("session_id") == sess_id and st.get("thought_id") == thought_id and st.get("kind") == kind:
                # Already exists: do not create duplicate
                return st
        st_id = "st_step_" + uuid.uuid4().hex[:26].upper()
        st_row = {
            "id": st_id,
            "session_id": sess_id,
            "thought_id": thought_id,
            "status": "proposed",
            "kind": kind,
            "step_description": step_obj.get("step_description"),
            "expected_outcome": step_obj.get("expected_outcome"),
            "next_step_conditions": step_obj.get("next_step_conditions") if isinstance(step_obj.get("next_step_conditions"), list) else None,
            "recommended_tools": step_obj.get("recommended_tools"),
            "created_at": now,
            "updated_at": now,
        }
        steps.append(st_row)
        return st_row

    # Supersede previous proposed current steps for this session when a new current_step arrives
    if current_step is not None:
        for st in steps:
            if not isinstance(st, dict):
                continue
            if st.get("session_id") == sess_id and st.get("kind") == "current" and st.get("status") == "proposed":
                st["status"] = "superseded"
                st["updated_at"] = now
        _upsert_step("current", current_step)

    if previous_steps is not None:
        # store snapshot as kind=previous; uniqueness prevents multiple rows, but product may want multiple
        # To mirror "array", we store only one normalized previous row from the latest tool call and keep embedded array on thought.
        # If we want multiple, we'd need a different schema. So keep normalized first as representative.
        if len(previous_steps) > 0:
            _upsert_step("previous", previous_steps[0])

    _save("session_steps.json", steps)

    # ---- Update session fields from latest payload ----
    session["current_thought_number"] = max(sess_current, int(thought_number))
    session["estimated_total_thoughts"] = int(total_thoughts)
    session["next_thought_needed"] = bool(next_thought_needed)
    session["needs_more_thoughts"] = needs_more_thoughts if needs_more_thoughts is not None else session.get("needs_more_thoughts")
    session["remaining_steps"] = remaining_steps if remaining_steps is not None else session.get("remaining_steps")
    session["updated_at"] = now

    # May transition active -> completed when no more thoughts needed
    if session.get("status") == "active" and (next_thought_needed is False) and (needs_more_thoughts is False or needs_more_thoughts is None):
        session["status"] = "completed"
        session["completed_at"] = now

    for si, srow in enumerate(sessions):
        if isinstance(srow, dict) and srow.get("id") == sess_id:
            sessions[si] = session
            break
    _save("thinking_sessions.json", sessions)

    # Update api_key last_used_at
    active_key["last_used_at"] = now
    active_key["updated_at"] = now
    for ki, krow in enumerate(api_keys):
        if isinstance(krow, dict) and krow.get("id") == active_key.get("id"):
            api_keys[ki] = active_key
            break
    _save("api_keys.json", api_keys)

    _log("sequentialthinking_tools", "ok", api_key_id=active_key.get("id"), workspace_id=active_ws.get("id"), session_id=sess_id, message="Thought committed")
    return {
        "session": session,
        "thought": new_thought,
    }

def sequentialthinking_tools_whoami(api_key, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0517000" if __import__("os").path.isdir("./environment_mix/0517000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    start = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _log(status, api_key_id=None, workspace_id=None, message=None):
        latency_ms = int((time.time() - start) * 1000)
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": "sequentialthinking_tools_whoami",
            "api_key_id": api_key_id,
            "workspace_id": workspace_id,
            "status": status,
            "message": message,
            "latency_ms": latency_ms,
            "created_at": now,
        }
        reqs = _load("request_logs.json")
        if not isinstance(reqs, list):
            reqs = []
        reqs.append(row)
        _save("request_logs.json", reqs)

    def _enforce_rate_limits(api_key_id, workspace_id):
        reqs = _load("request_logs.json")
        if not isinstance(reqs, list):
            reqs = []
        def _parse(ts):
            try:
                return datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
            except Exception:
                return None
        now_dt = datetime.datetime.fromisoformat(now.replace("Z", "+00:00"))
        one_min_ago = now_dt - datetime.timedelta(minutes=1)
        day_ago = now_dt - datetime.timedelta(days=1)
        rpm = 0
        wday = 0
        for r in reqs:
            if not isinstance(r, dict):
                continue
            ts = _parse(r.get("created_at", ""))
            if ts is None:
                continue
            if r.get("api_key_id") == api_key_id and ts >= one_min_ago:
                rpm += 1
            if r.get("workspace_id") == workspace_id and ts >= day_ago:
                wday += 1
        if rpm >= 60:
            return _err("RATE_LIMIT", "Rate limit exceeded for API key (60 requests/minute).")
        if wday >= 1000:
            return _err("QUOTA_EXCEEDED", "Daily request quota exceeded for workspace (1000 requests/day).")
        return None

    if not isinstance(api_key, str) or not api_key.strip():
        _log("error", message="validation: api_key")
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string.")

    api_keys = _load("api_keys.json")
    workspaces = _load("workspaces.json")
    sessions = _load("thinking_sessions.json")
    if not isinstance(api_keys, list): api_keys = []
    if not isinstance(workspaces, list): workspaces = []
    if not isinstance(sessions, list): sessions = []

    ws_by_id = {w.get("id"): w for w in workspaces if isinstance(w, dict)}
    key_row = None
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        # authenticate by id or client-visible value; we do not have plaintext key, so accept id match OR key_hash exact match
        if api_key == k.get("id") or api_key == k.get("key_hash"):
            key_row = k
            break
    if key_row is None:
        _log("error", message="unauthorized: key not found")
        return _err("UNAUTHORIZED", "Invalid API key.")

    ws = ws_by_id.get(key_row.get("workspace_id"))
    if ws is None:
        _log("error", api_key_id=key_row.get("id"), message="workspace not found")
        return _err("NOT_FOUND", "Workspace for API key not found.")
    if key_row.get("status") != "active":
        _log("error", api_key_id=key_row.get("id"), workspace_id=ws.get("id"), message="revoked key")
        return _err("UNAUTHORIZED", "API key is revoked.")
    if ws.get("status") != "active":
        _log("error", api_key_id=key_row.get("id"), workspace_id=ws.get("id"), message="inactive workspace")
        return _err("UNAUTHORIZED", "Workspace is not active.")

    rl = _enforce_rate_limits(key_row.get("id"), ws.get("id"))
    if rl is not None:
        _log("error", api_key_id=key_row.get("id"), workspace_id=ws.get("id"), message=rl["error"]["message"])
        return rl

    # usage summary
    active_sessions = sum(1 for s in sessions if isinstance(s, dict) and s.get("workspace_id") == ws.get("id") and s.get("status") == "active")
    resp = {
        "api_key": {
            "id": key_row.get("id"),
            "workspace_id": key_row.get("workspace_id"),
            "name": key_row.get("name"),
            "status": key_row.get("status"),
            "allowed_tools": key_row.get("allowed_tools"),
            "last_used_at": key_row.get("last_used_at"),
            "created_at": key_row.get("created_at"),
            "updated_at": key_row.get("updated_at"),
        },
        "workspace": {
            "id": ws.get("id"),
            "name": ws.get("name"),
            "status": ws.get("status"),
            "max_active_sessions": ws.get("max_active_sessions"),
            "max_thoughts_per_session": ws.get("max_thoughts_per_session"),
            "created_at": ws.get("created_at"),
            "updated_at": ws.get("updated_at"),
        },
        "usage": {
            "active_sessions": active_sessions,
            "max_active_sessions": ws.get("max_active_sessions"),
            "rate_limit": {"requests_per_minute": 60},
            "quota": {"requests_per_day": 1000},
        }
    }

    key_row["last_used_at"] = now
    key_row["updated_at"] = now
    _save("api_keys.json", api_keys)

    _log("ok", api_key_id=key_row.get("id"), workspace_id=ws.get("id"))
    return resp

def sequentialthinking_tools_create_session(api_key, tool_context, session_id=None, title=None, estimated_total_thoughts=None, **_extra):
    import json, os, datetime, time, uuid
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0517000" if __import__("os").path.isdir("./environment_mix/0517000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now_dt = datetime.datetime.now(datetime.timezone.utc).replace(microsecond=0)
    now = now_dt.isoformat().replace("+00:00", "Z")

    def _parse_ts(ts):
        if not isinstance(ts, str) or not ts:
            return None
        try:
            return datetime.datetime.fromisoformat(ts.replace("Z", "+00:00"))
        except Exception:
            return None

    def _log(status, api_key_id=None, workspace_id=None, session_id=None, message=None, error_code=None):
        latency_ms = int((time.time() - t0) * 1000)
        row = {
            "id": "req_" + uuid.uuid4().hex,
            "endpoint": "sequentialthinking_tools_create_session",
            "api_key_id": api_key_id,
            "workspace_id": workspace_id,
            "session_id": session_id,
            "status": status,
            "message": message,
            "error_code": error_code,
            "latency_ms": latency_ms,
            "created_at": now,
        }
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        logs.append(row)
        _save("request_logs.json", logs)

    def _enforce_limits(api_key_id, workspace_id):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        one_min_ago = now_dt - datetime.timedelta(minutes=1)
        day_ago = now_dt - datetime.timedelta(days=1)
        rpm = 0
        wday = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            ts = _parse_ts(r.get("created_at"))
            if ts is None:
                continue
            if api_key_id and r.get("api_key_id") == api_key_id and ts >= one_min_ago:
                rpm += 1
            if workspace_id and r.get("workspace_id") == workspace_id and ts >= day_ago:
                wday += 1
        if rpm >= 120:
            return _err("RATE_LIMIT", "Rate limit exceeded (120 requests/min per key).", limit="120/min", scope="api_key")
        if wday >= 20000:
            return _err("QUOTA_EXCEEDED", "Daily quota exceeded (20000 requests/day per workspace).", limit="20000/day", scope="workspace")
        return None

    # Validate inputs
    if not isinstance(api_key, str) or not api_key.strip():
        _log("error", message="Invalid api_key", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "api_key must be a non-empty string.", field="api_key")
    if not isinstance(tool_context, list) or len(tool_context) < 1 or any((not isinstance(x, str) or not x.strip()) for x in tool_context):
        _log("error", message="Invalid tool_context", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "tool_context must be a non-empty array of non-empty strings.", field="tool_context")
    if session_id is not None and (not isinstance(session_id, str) or not session_id.strip()):
        _log("error", message="Invalid session_id", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "session_id must be a non-empty string when provided.", field="session_id")
    if title is not None and not isinstance(title, str):
        _log("error", message="Invalid title", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "title must be a string when provided.", field="title")
    if estimated_total_thoughts is not None:
        if not isinstance(estimated_total_thoughts, int) or isinstance(estimated_total_thoughts, bool) or estimated_total_thoughts < 1:
            _log("error", message="Invalid estimated_total_thoughts", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "estimated_total_thoughts must be an integer >= 1 when provided.", field="estimated_total_thoughts")

    # Authenticate api_key by id (client-visible) OR by matching stored id (no plaintext available for hashes)
    api_keys = _load("api_keys.json")
    if isinstance(api_keys, dict) and "rows" in api_keys:
        api_keys = api_keys.get("rows")
    if not isinstance(api_keys, list):
        api_keys = []

    key_row = None
    for k in api_keys:
        if not isinstance(k, dict):
            continue
        if k.get("id") == api_key:
            key_row = k
            break
    if not key_row or key_row.get("status") != "active":
        _log("error", api_key_id=key_row.get("id") if key_row else None, message="Unauthorized", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API key is not active or not found.")

    workspaces = _load("workspaces.json")
    if isinstance(workspaces, dict) and "rows" in workspaces:
        workspaces = workspaces.get("rows")
    if not isinstance(workspaces, list):
        workspaces = []
    ws = None
    for w in workspaces:
        if isinstance(w, dict) and w.get("id") == key_row.get("workspace_id"):
            ws = w
            break
    if not ws or ws.get("status") != "active":
        _log("error", api_key_id=key_row.get("id"), workspace_id=key_row.get("workspace_id"), message="Workspace inactive", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Workspace is not active for this API key.")

    lim = _enforce_limits(key_row.get("id"), ws.get("id"))
    if lim:
        _log("error", api_key_id=key_row.get("id"), workspace_id=ws.get("id"), message=lim["error"]["message"], error_code=lim["error"]["code"])
        return lim

    allowed = key_row.get("allowed_tools")
    if not isinstance(allowed, list) or len(allowed) < 1:
        _log("error", api_key_id=key_row.get("id"), workspace_id=ws.get("id"), message="Key has no allowed tools", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API key has no allowed_tools configured.")
    allowed_set = set([x for x in allowed if isinstance(x, str)])

    if any((t not in allowed_set) for t in tool_context):
        _log("error", api_key_id=key_row.get("id"), workspace_id=ws.get("id"), message="tool_context not subset", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "tool_context must be a subset of api_key.allowed_tools.", field="tool_context")

    sessions = _load("thinking_sessions.json")
    if isinstance(sessions, dict) and "rows" in sessions:
        sessions = sessions.get("rows")
    if not isinstance(sessions, list):
        sessions = []

    # If session_id provided and exists, ensure it belongs to same workspace; idempotent return if already exists
    if session_id is not None:
        for s in sessions:
            if isinstance(s, dict) and s.get("id") == session_id:
                if s.get("workspace_id") != ws.get("id"):
                    _log("error", api_key_id=key_row.get("id"), workspace_id=ws.get("id"), session_id=session_id, message="Session id conflict", error_code="CONFLICT")
                    return _err("CONFLICT", "session_id already exists in a different workspace.", session_id=session_id)
                # idempotent: update tool_context if same? real API often returns existing without mutation
                _log("ok", api_key_id=key_row.get("id"), workspace_id=ws.get("id"), session_id=session_id, message="Idempotent create (exists)")
                return {"session": s}

    # Enforce active session quota
    active_count = 0
    for s in sessions:
        if isinstance(s, dict) and s.get("workspace_id") == ws.get("id") and s.get("status") == "active":
            active_count += 1
    max_active = ws.get("max_active_sessions")
    if not isinstance(max_active, int) or isinstance(max_active, bool) or max_active < 1:
        _log("error", api_key_id=key_row.get("id"), workspace_id=ws.get("id"), message="Workspace max_active_sessions invalid", error_code="CONFLICT")
        return _err("CONFLICT", "Workspace configuration invalid: max_active_sessions must be >= 1.", workspace_id=ws.get("id"))
    if active_count >= max_active:
        _log("error", api_key_id=key_row.get("id"), workspace_id=ws.get("id"), message="Active session quota exceeded", error_code="QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Workspace active-session quota exceeded.", workspace_id=ws.get("id"), max_active_sessions=max_active)

    if session_id is None:
        session_id = "st_sess_" + uuid.uuid4().hex[:26].upper()

    sess = {
        "id": session_id,
        "workspace_id": ws.get("id"),
        "api_key_id": key_row.get("id"),
        "status": "active",
        "title": title if title is not None else None,
        "tool_context": list(tool_context),
        "current_thought_number": 0,
        "estimated_total_thoughts": int(estimated_total_thoughts) if estimated_total_thoughts is not None else 1,
        "next_thought_needed": True,
        "needs_more_thoughts": None,
        "remaining_steps": None,
        "created_at": now,
        "updated_at": now,
        "completed_at": None,
    }
    sessions.append(sess)
    _save("thinking_sessions.json", sessions)

    # Update api_key usage
    key_row["last_used_at"] = now
    key_row["updated_at"] = now
    for i, k in enumerate(api_keys):
        if isinstance(k, dict) and k.get("id") == key_row.get("id"):
            api_keys[i] = key_row
            break
    _save("api_keys.json", api_keys)

    _log("ok", api_key_id=key_row.get("id"), workspace_id=ws.get("id"), session_id=session_id, message="Session created")
    return {"session": sess}

