        return _err("NOT_FOUND", "Workspace for API key not found.")
    if key_row.get("status") != "active":
        _log("error", api_key_id=key_row.get("id"), workspace_id=ws.get("id"), message="revoked key")
        return _err("UNAUTHORIZED", "API key is revoked.")
    if ws.get("status") != "active":
        _log("error", api_key_id=key_row.get("id"), workspace_id=ws.get("id"), message="inactive workspace")
        return _err("UNAUTHORIZED", "Workspace is not active.")

    rl = _enforce_rate_limits(key_row.get("id"), ws.get("id"))
    if rl is not None:
        _log("error", api_key_id=key_row.get("id"), workspace_id=ws.get("id"), session_id=session_id, message=rl["error"]["message"])
        return rl

    sess = None
    for s in sessions:
        if isinstance(s, dict) and s.get("id") == session_id:
            sess = s
            break
    if sess is None:
        _log("error", api_key_id=key_row.get("id"), workspace_id=ws.get("id"), session_id=session_id, message="session not found")
        return _err("NOT_FOUND", "Session not found.")
    if sess.get("workspace_id") != ws.get("id"):
        _log("error", api_key_id=key_row.get("id"), workspace_id=ws.get("id"), session_id=session_id, message="unauthorized workspace mismatch")
        return _err("UNAUTHORIZED", "Session does not belong to the authenticated workspace.")

    out = {"session": sess}

    inc = include or []
    if "latest_thought" in inc:
        latest = None
        latest_num = -1
        latest_dt = None
        for t in thoughts:
            if not isinstance(t, dict):
                continue
            if t.get("session_id") != session_id:
                continue
            if t.get("status") == "deleted":
                continue
            tn = t.get("thought_number")
            try:
                dt = datetime.datetime.fromisoformat(str(t.get("created_at", "")).replace("Z", "+00:00"))
            except Exception:
                dt = None
            if isinstance(tn, int) and tn > latest_num:
                latest = t
                latest_num = tn
                latest_dt = dt
            elif isinstance(tn, int) and tn == latest_num and dt is not None and (latest_dt is None or dt > latest_dt):
                latest = t
                latest_dt = dt
        out["latest_thought"] = latest

    if "steps_summary" in inc:
        proposed_current = None
        for st in steps:
            if not isinstance(st, dict):
                continue
            if st.get("session_id") != session_id:
                continue
            if st.get("kind") == "current" and st.get("status") == "proposed":
                proposed_current = st
                break
        prev_count = sum(1 for st in steps if isinstance(st, dict) and st.get("session_id") == session_id and st.get("kind") == "previous")
        out["steps_summary"] = {
            "current_step": proposed_current,
            "previous_steps_count": prev_count,
        }

    key_row["last_used_at"] = now
    key_row["updated_at"] = now
    _save("api_keys.json", api_keys)

    _log("ok", api_key_id=key_row.get("id"), workspace_id=ws.get("id"), session_id=session_id)
    return out

def sequentialthinking_tools_list_sessions(api_key, status=None, created_after=None, created_before=None, limit=None, cursor=None, order=None, **_extra):
    import json, os, datetime, time, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0517000" if __import__("os").path.isdir("./environment_mix/0517000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    requests_file = "request_logs.json"

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_rfc3339(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return None
        s2 = s.strip()
        if s2.endswith("Z"):
            s2 = s2[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(s2)
        except ValueError:
            return None
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _dt_from_row(v):
        if not isinstance(v, str):
            return None
        return _parse_rfc3339(v)

    def _log(auth_key_id, workspace_id, req_status, error_code=None):
        try:
            logs = _load(requests_file)
            if not isinstance(logs, list):
                logs = []
            logs.append({
                "id": "req_" + datetime.datetime.now(datetime.timezone.utc).strftime("%Y%m%d%H%M%S%f"),
                "endpoint": "sequentialthinking_tools_list_sessions",
                "api_key_id": auth_key_id,
                "workspace_id": workspace_id,
                "status": req_status,
                "error_code": error_code,
                "latency_ms": int((time.time() - t0) * 1000),
                "created_at": _now_iso()
            })
            _save(requests_file, logs)
        except Exception:
            pass

    def _auth_from_key_param(k):
        if not isinstance(k, str) or not k:
            return None, None, _err("VALIDATION_ERROR", "api_key must be a non-empty string", field="api_key")
        keys = _load("api_keys.json")
        workspaces = _load("workspaces.json")
        key_row = None
        # Authenticate by matching client-visible value or id; key_hash cannot be checked.
        for r in keys if isinstance(keys, list) else []:
            if r.get("id") == k:
                key_row = r
                break
        if key_row is None:
            # accept any row whose key_hash equals provided (treat as "client-visible value" fallback)
            for r in keys if isinstance(keys, list) else []:
                if r.get("key_hash") == k:
                    key_row = r
                    break
        if key_row is None:
            return None, None, _err("UNAUTHORIZED", "Invalid API key")
        if key_row.get("status") != "active":
            return None, None, _err("UNAUTHORIZED", "API key is not active")
        ws_id = key_row.get("workspace_id")
        ws_row = None
        for w in workspaces if isinstance(workspaces, list) else []:
            if w.get("id") == ws_id:
                ws_row = w
                break
        if ws_row is None:
            return None, None, _err("UNAUTHORIZED", "Workspace not found for API key")
        if ws_row.get("status") != "active":
            return None, None, _err("UNAUTHORIZED", "Workspace is not active")
        return key_row, ws_row, None

    # Validate inputs
    if limit is None:
        limit = 50
    if order is None:
        order = "updated_at_desc"
    if not isinstance(limit, int) or limit < 1 or limit > 200:
        _log(None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 200", field="limit")
    if status is not None:
        if not isinstance(status, str) or status not in ("active", "completed", "cancelled", "archived"):
            _log(None, None, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid status", field="status")
    if order not in ("created_at_asc", "created_at_desc", "updated_at_asc", "updated_at_desc"):
        _log(None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid order", field="order")

    ca = _parse_rfc3339(created_after)
    if created_after is not None and ca is None:
        _log(None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "created_after must be an RFC 3339 timestamp", field="created_after")
    cb = _parse_rfc3339(created_before)
    if created_before is not None and cb is None:
        _log(None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "created_before must be an RFC 3339 timestamp", field="created_before")

    # Cursor decoding: base64url of JSON {"offset":int}
    offset = 0
    if cursor is not None:
        if not isinstance(cursor, str) or not cursor:
            _log(None, None, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "cursor must be a non-empty string", field="cursor")
        try:
            padded = cursor + "=" * (-len(cursor) % 4)
            payload = base64.urlsafe_b64decode(padded.encode("utf-8")).decode("utf-8")
            obj = json.loads(payload)
            offset = int(obj.get("offset", 0))
            if offset < 0:
                raise ValueError("offset<0")
        except Exception:
            _log(None, None, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid cursor", field="cursor")

    key_row, ws_row, auth_err = _auth_from_key_param(api_key)
    if auth_err:
        _log(None, None, "error", auth_err["error"]["code"])
        return auth_err

    # Update last_used_at
    try:
        keys = _load("api_keys.json")
        if isinstance(keys, list):
            for r in keys:
                if r.get("id") == key_row.get("id"):
                    r["last_used_at"] = _now_iso()
                    r["updated_at"] = r.get("updated_at") or _now_iso()
                    break
            _save("api_keys.json", keys)
    except Exception:
        pass

    sessions = _load("thinking_sessions.json")
    if not isinstance(sessions, list):
        sessions = []

    ws_id = ws_row.get("id")
    filtered = []
    for s in sessions:
        if s.get("workspace_id") != ws_id:
            continue
        if status is not None and s.get("status") != status:
            continue
        s_created = _dt_from_row(s.get("created_at"))
        if ca is not None:
            if s_created is None or s_created < ca:
                continue
        if cb is not None:
            if s_created is None or s_created >= cb:
                continue
        filtered.append(s)

    def _sort_key(row):
        if order.startswith("created_at"):
            dt = _dt_from_row(row.get("created_at"))
        else:
            dt = _dt_from_row(row.get("updated_at"))
        if dt is None:
            dt = datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return dt, (row.get("id") or "")

    reverse = order.endswith("_desc")
    filtered.sort(key=_sort_key, reverse=reverse)

    total = len(filtered)
    page = filtered[offset: offset + limit]
    next_offset = offset + len(page)
    has_more = next_offset < total
    next_cursor = None
    if has_more:
        payload = json.dumps({"offset": next_offset}, separators=(",", ":")).encode("utf-8")
        next_cursor = base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")

    _log(key_row.get("id"), ws_id, "ok", None)
    return {
        "sessions": page,
        "pagination": {
            "total": total,
            "limit": limit,
            "cursor": cursor,
            "has_more": has_more,
            "next_cursor": next_cursor
        }
    }

